          <TabBar
            tabs={[]}
            activeTabId=""
            onActivate={onActivateTab}
            onClose={onCloseTab}
            onAdd={onAddTab}
            onAddBrowser={onAddBrowserTab}
            onAddMarkdown={onAddMarkdown}
            onAddMobileEmulator={onAddMobileEmulator}
            onOpenSettings={onOpenSettings}
